import { Menubar as MenubarPrimitive } from "@base-ui/react/menubar";
import { DropdownMenu, DropdownMenuTrigger, DropdownMenuContent, DropdownMenuItem /* … */ } from "./dropdown-menu";

function Menubar(p: MenubarPrimitive.Props) { return <MenubarPrimitive data-slot="menubar" {...p} /> }
function MenubarMenu(p: React.ComponentProps<typeof DropdownMenu>) { return <DropdownMenu data-slot="menubar-menu" {...p} /> }
function MenubarItem(p: React.ComponentProps<typeof DropdownMenuItem>) { return <DropdownMenuItem data-slot="menubar-item" {...p} /> }

import { mergeProps } from "@base-ui/react/merge-props";
