function ToolbarLabel({ className, render, ...props }: useRender.ComponentProps<"div">) {
  return useRender({
    defaultTagName: "div",
    props: mergeProps<"div">({ className: cn("…", className) }, props),
    render,
    state: { slot: "toolbar-label" },
  });
}

