// item is chrome-agnostic; same JSX works in every container
export function TldrawUiMenuItem({ id, icon, kbd, label, onSelect, isSelected }: TLUiMenuItemProps) {
  const { type: menuType, sourceId } = useTldrawUiMenuContext()
  switch (menuType) {
    case 'menu':    return <TldrawUiDropdownMenuItem>…<TldrawUiKbd>{kbd}</TldrawUiKbd></TldrawUiDropdownMenuItem>
    case 'toolbar': return <TldrawUiToolbarButton type="tool" aria-pressed={…}><Icon icon={icon!}/></TldrawUiToolbarButton>
    case 'keyboard-shortcuts': return <div className="…key-pair">{labelStr}<TldrawUiKbd>{kbd}</TldrawUiKbd></div>
    default: throw exhaustiveSwitchError(menuType)
  }
}

interface TLUiComponents {
  Toolbar?: ComponentType | null; ContextMenu?: ComponentType<TLUiContextMenuProps> | null
  MainMenu?: …| null; PageMenu?: …| null; StylePanel?: …| null; TopPanel?: …| null /* 31 keys */
}
// provider: defaults first, host overrides spread last
value={{ Toolbar: DefaultToolbar, PageMenu: DefaultPageMenu, …, ..._overrides }}
