// library
export const DefaultToolbar = memo(function DefaultToolbar({ children, orientation = 'horizontal', minItems = 4, maxItems, … }: DefaultToolbarProps) {
  return <OverflowingToolbar …>{children ?? <DefaultToolbarContent />}</OverflowingToolbar>
})
// host: add + reorder, no source touched
function MyToolbar() {
  return <DefaultToolbar><ToolbarItem tool="select"/><MyToolbarItem/><ToolbarItem tool="frame"/></DefaultToolbar>
}
<Tldraw components={{ Toolbar: MyToolbar }} overrides={{ tools: (ed, tools) => ({...tools, mine: {…}}) }} />

interface TLUiToolItem { id: string; label: TranslationKey; icon: IconType | TLUiIconJsx
  onSelect(source: TLUiEventSource): void; kbd?: string; readonlyOk?: boolean; meta?: Record<string, any> }
interface TLUiOverrides {
  tools?(editor: Editor, tools: TLUiToolsContextType, helpers: TLUiOverrideHelpers): TLUiToolsContextType
  actions?(editor, actions: TLUiActionsContextType, helpers): TLUiActionsContextType
}
// mergeOverrides folds an array left-to-right: schema = override.tools(editor, schema, helpers)
